#!/usr/bin/perl
use strict;
use warnings;
use File::Find;
use File::Basename;

my $ROOT = '/bench/repo';
my $MODULE = 'github.com/usememos/memos';

# --- Phase 1: collect internal declarations ---
# key: "importpath|recv|name" -> { file, pkg, recv, name, importpath, exported }
my %decls;
my @decl_list;

sub read_go_file {
    my ($path) = @_;
    open my $fh, '<', $path or return undef;
    local $/;
    my $content = <$fh>;
    close $fh;
    return $content;
}

sub get_package {
    my ($content) = @_;
    if ($content =~ /^package\s+(\w+)/m) {
        return $1;
    }
    return '';
}

sub file_to_import_path {
    my ($path) = @_;
    $path =~ s/^\Q$ROOT\E\/?//;
    $path =~ s/\.go$//;
    $path =~ s/\/[^\/]+$//;  # remove filename, keep dir
    return "$MODULE/$path";
}

sub parse_imports {
    my ($content) = @_;
    my %imports;  # alias -> full path
    while ($content =~ /import\s+(?:\(\s*([\s\S]*?)\s*\)|"([^"]+)")/g) {
        my $block = $1 // $2;
        next unless defined $block;
        if (!defined $1) {
            # single import
            my $path = $2;
            my $alias = (split /\//, $path)[-1];
            $alias =~ s/-.*//;
            $imports{$alias} = $path;
            next;
        }
        while ($block =~ /(?:(\w+)\s+)?"([^"]+)"/g) {
            my ($alias, $path) = ($1, $2);
            $alias //= (split /\//, $path)[-1];
            $alias =~ s/-.*//;
            $imports{$alias} = $path;
        }
    }
    return %imports;
}

sub parse_functions {
    my ($content, $file, $pkg, $importpath) = @_;
    my @funcs;
    # Remove comments roughly
    my $clean = $content;
    $clean =~ s/\/\/.*$//mg;
    $clean =~ s/\/\*[\s\S]*?\*\///g;

    while ($clean =~ /^func\s+(?:\(([^)]*)\)\s+)?(\w+)\s*\(/gm) {
        my ($recv, $name) = ($1 // '', $2);
        my $rectype = '';
        if ($recv =~ /\*?\s*(\w+)/) {
            $rectype = $1;
        }
        push @funcs, {
            file => $file,
            pkg => $pkg,
            recv => $rectype,
            name => $name,
            importpath => $importpath,
            key => "$importpath|$rectype|$name",
        };
    }
    return @funcs;
}

# Collect all .go files and their functions (for caller identification)
my %all_funcs;  # file -> list of {name, recv, start, end approx via index}
my %file_pkg;
my %file_imports;
my @all_go_files;

find(sub {
    return unless /\.go$/;
    push @all_go_files, $File::Find::name;
}, $ROOT);

for my $file (@all_go_files) {
    my $content = read_go_file($file);
    next unless $content;
    my $pkg = get_package($content);
    $file_pkg{$file} = $pkg;
    $file_imports{$file} = { parse_imports($content) };

    my $importpath = file_to_import_path($file);

    if ($file =~ m{^\Q$ROOT\E/internal/}) {
        my @fns = parse_functions($content, $file, $pkg, $importpath);
        for my $fn (@fns) {
            $decls{$fn->{key}} = $fn;
            push @decl_list, $fn;
        }
    }
}

# Build reverse map: importpath -> possible aliases per file
# For each internal decl, we need to find calls

# Parse function boundaries for caller tracking (all files)
# Simple approach: split by func declarations, track caller key per chunk
my %caller_chunks;  # chunk_id -> { caller_key, file, body }

sub caller_key {
    my ($file, $pkg, $recv, $name) = @_;
    my $rel = $file;
    $rel =~ s/^\Q$ROOT\E\/?//;
    return "$rel|$pkg|${recv}|$name";
}

for my $file (@all_go_files) {
    my $content = read_go_file($file);
    next unless $content;
    my $pkg = $file_pkg{$file};
    my $clean = $content;
    $clean =~ s/\/\/.*$//mg;
    $clean =~ s/\/\*[\s\S]*?\*\///g;

    my @matches;
    while ($clean =~ /\G([\s\S]*?)^func\s+(?:\(([^)]*)\)\s+)?(\w+)\s*\(/gm) {
        my ($before, $recv, $name) = ($1, $2 // '', $3);
        my $rectype = '';
        if ($recv =~ /\*?\s*(\w+)/) { $rectype = $1; }
        my $pos = pos($clean) - 1;
        push @matches, { pos => $pos, recv => $rectype, name => $name };
    }

    for my $i (0..$#matches) {
        my $start = $matches[$i]{pos};
        my $end = ($i < $#matches) ? $matches[$i+1]{pos} : length($clean);
        my $body = substr($clean, $start, $end - $start);
        my $ck = caller_key($file, $pkg, $matches[$i]{recv}, $matches[$i]{name});
        $caller_chunks{$ck} = { body => $body, file => $file, pkg => $pkg, imports => $file_imports{$file} };
    }
}

# Count fan-in for each internal decl
my %fanin;      # key -> set of caller keys
my %callcount;  # key -> total call sites

for my $decl (@decl_list) {
    my $target_key = $decl->{key};
    my $target_name = $decl->{name};
    my $target_path = $decl->{importpath};
    my $target_pkg = $decl->{pkg};
    my $target_recv = $decl->{recv};

    $fanin{$target_key} = {};
    $callcount{$target_key} = 0;

    for my $ck (keys %caller_chunks) {
        my $chunk = $caller_chunks{$ck};
        my $body = $chunk->{body};
        my %imports = %{$chunk->{imports}};

        # Skip self-calls within same function (declaration line)
        my $found = 0;

        if ($target_recv eq '') {
            # Package-level function
            # Pattern 1: same package, same directory - unqualified call
            if ($chunk->{file} =~ m{^\Q$ROOT\E/internal/}) {
                my $chunk_import = file_to_import_path($chunk->{file});
                # same package if same directory
                my ($td) = ($target_path =~ /^(.*)$/);
                my ($cd) = ($chunk_import =~ /^(.*)$/);
                # compare parent dirs
                if (dirname($chunk->{file}) eq dirname($decl->{file}) && $file_pkg{$chunk->{file}} eq $target_pkg) {
                    my $pat = qr/(?<![.\w])$target_name\s*\(/;
                    if ($body =~ /$pat/g) {
                        $found = 1;
                        my $n = () = $body =~ /$pat/g;
                        $callcount{$target_key} += $n;
                    }
                }
            }

            # Pattern 2: qualified call via import alias
            for my $alias (keys %imports) {
                next unless $imports{$alias} eq $target_path;
                my $pat = qr/\b\Q$alias\E\.$target_name\s*\(/;
                if ($body =~ /$pat/) {
                    $found = 1;
                    my $n = () = $body =~ /$pat/g;
                    $callcount{$target_key} += $n;
                }
            }

            # Pattern 3: full path unlikely in Go source, skip
        } else {
            # Method - harder without type inference
            # Match .MethodName( for methods
            my $pat = qr/\.${target_name}\s*\(/;
            # Only count if file imports the package OR is in same package
            my $can_call = 0;
            if (dirname($chunk->{file}) eq dirname($decl->{file}) && $file_pkg{$chunk->{file}} eq $target_pkg) {
                $can_call = 1;
            }
            for my $alias (values %imports) {
                if ($alias eq $target_path) { $can_call = 1; last; }
            }
            # Also any file in repo might use interface - count all .Method(
            if ($body =~ /$pat/) {
                # filter: if multiple types have same method name, overcount risk
                $found = 1;
                my $n = () = $body =~ /$pat/g;
                $callcount{$target_key} += $n;
            }
        }

        if ($found) {
            $fanin{$target_key}{$ck} = 1;
        }
    }
}

# Sort by fan-in
my @sorted = sort {
    scalar(keys %{$fanin{$b}}) <=> scalar(keys %{$fanin{$a}})
        || $callcount{$b} <=> $callcount{$a}
} @decl_list;

print "TOP 30 by unique caller count:\n";
print "=" x 80, "\n";
my $i = 0;
for my $decl (@sorted) {
    last if ++$i > 30;
    my $k = $decl->{key};
    my $fi = scalar(keys %{$fanin{$k}});
    my $cs = $callcount{$k};
    my $sym = $decl->{recv} ? "($decl->{recv}).$decl->{name}" : $decl->{name};
    print sprintf("%3d callers, %3d sites | %s | %s\n", $fi, $cs, $sym, $decl->{file});
}

print "\n\nTOTAL internal declarations: ", scalar(@decl_list), "\n";
PERLEOF
perl /tmp/fanin.pl 2>&1 | head -50

