    while ($clean =~ /\G([\s\S]*?)^func\s+(?:\(([^)]*)\)\s+)?(\w+)\s*\(/gm) {
        my ($recv,$name)=($2//'',$3); my $rt=''; $rt=$1 if $recv=~/\*?\s*(\w+)/;
        push @m,{pos=>pos($clean)-1,recv=>$rt,name=>$name};
