    }
}

sub count_pat { my($body,$pat)=@_; my $n=0; while($body=~/$pat/g){$n++} $n }
sub can_call_package { my($ch,$tp,$tpkg,$td)=@_; return 1 if $ch->{dir} eq $td && $ch->{pkg} eq $tpkg; return 1 if $ch->{rev}{$tp}; return 0 }

my (%fanin,%callcount);
