        if ($tr eq '') {
            if ($ch->{dir} eq $td && $ch->{pkg} eq $tpkg) {
                $sites += count_pat($body, qr/(?<![.\w])$tn\s*\(/);
            }
            if ($ch->{rev}{$tp}) {
                for my $alias (@{$ch->{rev}{$tp}}) {
                    $sites += count_pat($body, qr/(?<![.\w])\Q$alias\E\.$tn\s*\(/);
