            my $pat=qr/(?<![.\w])(\w+)\.$tn\s*\(/;
            while ($body =~ /$pat/g) {
                next if exists $ch->{imports}{$1};
                $sites++;
            }
        }
        if ($sites>0) { $fanin{$tk}{$ck}=1; $callcount{$tk}+=$sites; }
    }
    $decl->{fanin}=scalar(keys %{$fanin{$tk}}); $decl->{sites}=$callcount{$tk};
}

