        my $sym=$d->{recv}?"( $d->{recv}).$d->{name}":"$d->{pkg}.$d->{name}"; $sym=~s/^\( /(/;
        print sprintf("%3d callers, %3d sites | %-45s | %s\n",$d->{fanin},$d->{sites},$sym,$d->{file});
    }
}

